# ── 167: Central Venous Pressure Monitoring ──────────────────────────────────
kps += [
  {"id":"cvp-monitoring-1","topic":"Central Venous Pressure Monitoring","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"What is the normal CVP range?","answer":"2-6 mm Hg; CVP <5 may indicate fluid responsiveness; CVP >16 suggests volume overload","rationale":"CVP reflects right atrial pressure and serves as a rough surrogate for right ventricular preload, though predictive value is limited in the mid-range.","bloom":"recall","source":[{"book":"Miller/Baby Miller","page":387}],"confusable_with":"PCWP normal range (6-12 mm Hg)"},
  {"id":"cvp-monitoring-2","topic":"Central Venous Pressure Monitoring","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"What three conditions must be met for SPV, PPV, and SVV to accurately predict volume responsiveness?","answer":"Regular cardiac rhythm + closed-chest positive-pressure ventilation + no excessively high PEEP","rationale":"These dynamic indices rely on consistent respiratory-induced fluctuations in venous return; arrhythmias or spontaneous breathing invalidate their interpretation.","bloom":"analyze","source":[{"book":"Miller/Baby Miller","page":395}],"confusable_with":"CVP as volume responsiveness predictor"},
  {"id":"cvp-monitoring-3","topic":"Central Venous Pressure Monitoring","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"What is the fundamental limitation of using absolute CVP values to guide fluid management?","answer":"Absolute CVP is NOT reliably predictive of intravascular volume status because vascular compliance changes rapidly; only extreme values (very low or very high) guide management","rationale":"The same CVP can occur at very different volume states in different patients, making it unreliable as a single fluid guide.","bloom":"analyze","source":[{"book":"Miller/Baby Miller","page":396}],"confusable_with":"CVP as direct measure of preload volume"},
  {"id":"cvp-monitoring-4","topic":"Central Venous Pressure Monitoring","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"On bedside ultrasound, what IVC findings suggest hypovolemia?","answer":"IVC diameter <1.7 cm OR >50% inspiratory collapse (collapsibility index >50%)","rationale":"A small, highly collapsible IVC indicates low right atrial filling pressure and predicts likely fluid responsiveness.","bloom":"apply","source":[{"book":"Stanford CA-1","page":46}],"confusable_with":"dilated fixed IVC indicating fluid overload"},
  {"id":"cvp-monitoring-5","topic":"Central Venous Pressure Monitoring","domain":"Anesthesia monitoring & equipment (anesthesia machine & circuits, ventilators, capnography & gas analysis, pulse oximetry, depth of anesthesia, neuromuscular monitoring, alarms & safety checks)","discipline":"anesthesia","stem":"When a CVP catheter is inserted from the left side, what tip position must be verified to avoid perforation?","answer":"The tip must not lie against the wall of the SVC — left-sided catheters make an acute downward turn and can abut the lateral wall, risking erosion and tamponade","rationale":"Left-sided venous anatomy forces catheters to angle sharply, creating a non-coaxial contact point with the SVC wall under pulsatile flow.","bloom":"analyze","source":[{"book":"Marino ICU Book","page":91}],"confusable_with":"right-sided catheter tip positioning"}
]

# ── 168: Chest wall resection and reconstruction ─────────────────────────────
